#!/usr/bin/env python3
"""swarmer: paths, safe writes, the local folder, the notes of the generated files and the checks of the public
material.

One module, used by the generator and by the command line, so that the rules are the same everywhere:
- no write follows a symbolic link, and every file is written through a temporary file and a replacement;
- the swarm folder is inside the project root and different from it;
- the local folder (the overrides) is one, the one of the configuration;
- a file is «generated by the swarm» only if it carries the note in the exact place;
- a file of the project is never renamed: every language's name is looked for, and a new one takes the name of the
  language of the installation (A.4);
- the public material contains no secrets, e-mail addresses, machine paths, words the project forbids (even when
  spelled differently) nor the markers with which swarmer.sh separates the files.
Standard library only.
"""
from __future__ import annotations

import html
import json
import os
import re
import sys
import tempfile
import unicodedata
import urllib.parse
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import compat as C  # noqa: E402

Error = C.Error
GENERATED = C.GENERATED_NOTES["en"]
FILE_MARK = "#==== swarmer.sh:"
END_OF_FILES = "SWARMER_END_OF_FILES"
END_OF_FILES_LINE = "end of files"
TMP_PREFIX = ".swarmer-"
FILE_MARKS = (FILE_MARK, C.OLD_MARKS["file_mark"])
END_MARKS = (END_OF_FILES, C.OLD_MARKS["end_of_files"])


# --- writes ---

def no_links(base: Path, p: Path) -> Path:
    """The path, if it is inside `base` and no component of it from `base` down is a symbolic link."""
    base = Path(base)
    p = Path(p)
    try:
        rel = p.relative_to(base)
    except ValueError:
        raise Error(f"{p} is not inside {base}")
    if ".." in rel.parts:
        raise Error(f"{p}: «..» is not allowed")
    current = base
    for part in rel.parts:
        current = current / part
        if current.is_symlink():
            raise Error(f"{current} is a symbolic link: not following it")
    return p


def write(base: Path, p: Path, data, mode: int | None = None) -> None:
    """Writes text or bytes to `p` (inside `base`), without following links, through a temporary file and os.replace."""
    p = no_links(base, p)
    no_links(base, p.parent)
    p.parent.mkdir(parents=True, exist_ok=True)
    no_links(base, p.parent)
    b = data.encode("utf-8") if isinstance(data, str) else data
    if mode is None and p.is_file():
        mode = p.stat().st_mode & 0o7777   # an existing file keeps its permissions
    elif mode is None:
        mode = 0o666 & ~_umask()
    fd, tmp = tempfile.mkstemp(dir=str(p.parent), prefix=TMP_PREFIX)
    try:
        with os.fdopen(fd, "wb") as f:
            f.write(b)
        if mode is not None:
            os.chmod(tmp, mode)
        os.replace(tmp, p)
    except BaseException:
        if os.path.exists(tmp):
            os.unlink(tmp)
        raise


def _umask() -> int:
    m = os.umask(0)
    os.umask(m)
    return m


def check_no_links(base: Path, ignore=frozenset()) -> None:
    """No symbolic link under `base` (a source to distribute or a copy to test), outside the folders and files of
    `ignore`, which are neither distributed nor copied."""
    base = Path(base)
    if base.is_symlink():
        raise Error(f"{base} is a symbolic link")
    for top, dirs, files in os.walk(base, followlinks=False):
        dirs[:] = [d for d in dirs if d not in ignore]
        for n in dirs + [f for f in files if f not in ignore]:
            p = Path(top) / n
            if p.is_symlink():
                raise Error(f"{p} is a symbolic link: not distributing nor following it")


def remove_file(base: Path, p: Path) -> None:
    p = no_links(base, p)
    p.unlink()


# --- localized names and files of the project (A.3, A.4) ---

def _i18n_files(swarm, lang: str) -> dict:
    """The section "files" of i18n/<lang>.json, joined with those of the extensions (5.2): the core wins."""
    if swarm is None:
        return {}
    out = {}
    ext = Path(swarm) / "extensions"
    for p in (sorted(ext.glob(f"*/i18n/{lang}.json")) if ext.is_dir() else []) + [Path(swarm) / "i18n" / f"{lang}.json"]:
        try:
            out.update(json.loads(p.read_text(encoding="utf-8")).get("files", {}) if p.is_file() else {})
        except (OSError, json.JSONDecodeError, AttributeError):
            continue
    return out


def localized_name(swarm, canonical: str, lang: str) -> str:
    """The name of a file or folder in the language: the section "files" of i18n/<lang>.json, then the table of
    compat.py; English is the identity."""
    if lang == "en":
        return canonical
    v = _i18n_files(swarm, lang).get(canonical)
    if isinstance(v, list):
        v = v[0] if v else None
    return v or C.FILE_NAMES.get(lang, {}).get(canonical, canonical)


def all_names(swarm, canonical: str) -> list[str]:
    """The name of a file or folder in every available language, the canonical first."""
    langs = list(C.LANGUAGES)
    if swarm is not None and (Path(swarm) / "i18n").is_dir():
        langs += sorted(p.stem for p in (Path(swarm) / "i18n").glob("*.json") if p.stem not in langs)
    return list(dict.fromkeys(localized_name(swarm, canonical, l) for l in langs))


def find_project_file(base, canonical: str, lang: str, swarm=None) -> Path:
    """A file of the project (A.4): the name of every language is looked for; the one that exists is used (never
    renamed, never duplicated); if none exists, the name of the language of the installation. Two names present
    together for the same role are an error."""
    base = Path(base)
    names = all_names(swarm, canonical)
    found = [n for n in names if (base / n).exists() or (base / n).is_symlink()]
    if len(found) > 1:
        raise Error(f"both {base / found[0]} and {base / found[1]} exist")
    if found:
        return base / found[0]
    return base / localized_name(swarm, canonical, lang)


# --- folders ---

def valid_folder(root: Path, folder: str) -> Path:
    """The swarm folder: relative, without «..», inside the root and different from it; double or trailing slashes
    are dropped."""
    if os.path.isabs(str(folder)):
        raise Error(f"--folder «{folder}»: a relative path inside the project is needed")
    folder = "/".join(x for x in str(folder).split("/") if x not in ("",))
    if not folder or os.path.isabs(folder) or ".." in Path(folder).parts or Path(folder) in (Path("."), Path("")):
        raise Error(f"--folder «{folder}»: a relative path inside the project is needed, without «..», not «.»")
    root = Path(root).resolve()
    s = (root / folder)
    no_links(root, s) if s.exists() else None
    if s.resolve() == root or root not in s.resolve().parents:
        raise Error(f"--folder «{folder}» is not inside {root}")
    return s


def state_dir(root: Path, lang: str = "en") -> Path:
    """The state folder of the project: .swarmer/ or its name in another language (both → error), otherwise the one
    of the language."""
    return find_project_file(root, ".swarmer", lang)


def config_path(root: Path, lang: str = "en") -> Path:
    return state_dir(root, lang) / "config.json"


def read_config_raw(root: Path) -> tuple[dict, Path | None]:
    """The configuration as written (its dialect) and its path, or ({}, None)."""
    p = config_path(root)
    if p.is_symlink():
        raise Error(f"{p} is a symbolic link")
    if not p.is_file():
        return {}, None
    try:
        raw = json.loads(p.read_text(encoding="utf-8"))
    except json.JSONDecodeError as e:
        raise Error(f"{p}: not json: {e}")
    if not isinstance(raw, dict):
        raise Error(f"{p}: an object is needed")
    return raw, p


_WARNED: set = set()


def config(root: Path) -> dict:
    """The configuration of the project in canonical form (C.2): folder, local, project_managed, models, prefix. A key
    the schema does not know (the 4.0 read a free dictionary) is kept, with a warning: the file is never rewritten for
    it."""
    raw, p = read_config_raw(root)
    unknown = []
    out = C.to_canonical(raw, C.CONFIG_SCHEMA, str(p), unknown) if raw else {}
    if unknown and str(p) not in _WARNED:
        _WARNED.add(str(p))
        print(f"{p}: unknown keys kept and ignored: " + ", ".join(unknown), file=sys.stderr)
    return out


def write_config(root: Path, cfg: dict, lang: str = "en") -> bool:
    """Writes the configuration only if it changes (semantic comparison), in its dialect; a new one in `lang`.
    Returns whether it wrote."""
    raw, p = read_config_raw(root)
    old = C.to_canonical(raw, C.CONFIG_SCHEMA, str(p), []) if raw else {}
    if p is not None and old == cfg:
        return False
    if p is None and not cfg:
        return False
    dialect = C.dialect_of(raw, C.CONFIG_SCHEMA, lang) if raw else lang
    out = C.to_dialect(cfg, C.CONFIG_SCHEMA, dialect, unknown=[])
    target = p or config_path(root, lang)
    write(root, target, json.dumps(out, ensure_ascii=False, indent=1) + "\n")
    return True


def local_folder(root: Path, swarm: Path) -> Path:
    """The folder of the local overrides: the one of config.json («local», relative to the root), otherwise
    <swarm>/local (or its name in another language, if it exists). If the configuration names an AGENTS.md file, the folder is the
    one that contains it."""
    loc = config(root).get("local")
    if loc:
        p = Path(loc)
        if p.is_absolute() or ".." in p.parts:
            raise Error(f"local «{loc}»: a relative path inside the project is needed")
        p = Path(root) / p
        return p.parent if p.suffix == ".md" else p
    return fixed_local(swarm)


def fixed_local(swarm: Path, lang: str | None = None) -> Path:
    """<inst>/local/ under the name of any language (the one that exists; a new one in the language of the
    installation)."""
    return find_project_file(swarm, "local", lang or installed_language(swarm), swarm)


def installed_language(swarm: Path) -> str:
    """The language of the installation from its files (LANGUAGE, then its 4.0 name), otherwise en."""
    for n in ("LANGUAGE", C.STATE_NAMES["LANGUAGE"]):
        p = Path(swarm) / n
        if p.is_file() and not p.is_symlink():
            v = p.read_text(encoding="utf-8").strip()
            if v:
                return v
    return "en"


def local_agents_file(root: Path, swarm: Path) -> Path:
    loc = config(root).get("local")
    if loc and Path(loc).suffix == ".md":
        return Path(root) / loc
    folder = local_folder(root, swarm)
    return find_project_file(folder, "AGENTS.md", installed_language(swarm), swarm)


def forbidden(root: Path, swarm: Path) -> tuple[list[str], bool]:
    """The words the project forbids and whether a list exists: FORBIDDEN.txt (under the name of any language) in
    the configured local folder, in <swarm>/local, and the files of SWARMER_FORBIDDEN and of its 4.0 alias. Never
    distributed."""
    cands = []
    for folder in (local_folder(root, swarm), fixed_local(swarm)):
        cands += [folder / n for n in all_names(swarm, "FORBIDDEN.txt")]
    cands += [Path(x) for x in C.env_list("SWARMER_FORBIDDEN")]
    out, found = [], False
    for p in dict.fromkeys(cands):
        if p.is_file():
            found = True
            out += [r.strip() for r in p.read_text(encoding="utf-8").splitlines() if r.strip() and not r.startswith("#")]
    return out, found


def has_override(root: Path, swarm: Path) -> bool:
    f = local_agents_file(root, swarm)
    if not f.is_file():
        return False
    t = f.read_text(encoding="utf-8")
    return any(f"— `{p}-" in t for p in C.AGENT_PREFIXES)


# --- the note of the generated files ---

def note(text: str, lang: str = "en") -> str:
    return f"<!-- {C.GENERATED_NOTES.get(lang, GENERATED)}: {text} -->"


def toml_note(text: str, lang: str = "en") -> str:
    """The GENERATED note of a TOML file (a Codex agent): a comment on the first line."""
    return f"# {C.GENERATED_NOTES.get(lang, GENERATED)}: {text}"


def is_generated(p: Path) -> bool:
    """True only if the GENERATED note is in the exact place: the first line after the YAML head (agents and skills),
    or the first line (documents; in a TOML file, a comment). A note elsewhere, for instance inside an «in short», does
    not count. The notes of 4.0 and 5.0, in both languages, are recognised."""
    try:
        if not p.is_file() or p.is_symlink():
            return False
        lines = p.read_text(encoding="utf-8").splitlines()
    except (OSError, UnicodeDecodeError):
        return False
    if p.suffix == ".toml":   # a Codex agent: the note is the comment of the first line
        return bool(lines) and bool(C.TOML_GENERATED_RE.match(lines[0]))
    i = 0
    if lines and lines[0] == "---":
        try:
            i = lines.index("---", 1) + 1
        except ValueError:
            return False
        while i < len(lines) and not lines[i].strip():
            i += 1
    return i < len(lines) and bool(C.GENERATED_RE.match(lines[i]))


# --- the public material ---

SECRETS = [re.compile(x) for x in (
    r"gh[opusr]_[A-Za-z0-9]{30,}", r"github_pat_[A-Za-z0-9_]{40,}", r"sk-[A-Za-z0-9_-]{20,}", r"hf_[A-Za-z0-9]{30,}",
    r"rpa_[A-Za-z0-9]{20,}", r"AKIA[0-9A-Z]{16}", r"xox[abpr]-[A-Za-z0-9-]{10,}", r"-----BEGIN [A-Z ]*PRIVATE KEY-----",
    r"(?i)(api[_-]?key|secret|password|token)\s*[:=]\s*['\"][^'\"\s]{12,}['\"]")]
EMAIL = re.compile(r"[A-Za-z0-9._%+-]+@(?!example\.(?:com|org)\b)[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}")
MACHINE_PATH = re.compile(r"(/home/(?!<)[A-Za-z_][A-Za-z0-9._-]*/|/Users/(?!<)[A-Za-z0-9._-]+/|/r[o]ot/|[A-Za-z]:\\+Users\\+"
                          r"|/tmp/claude-\d+)")
FILE_NAME = re.compile(r"^(?!(?:.*/)?\.\.?(?:/|$))[A-Za-z0-9_.][A-Za-z0-9_.-]*(?:/(?!\.\.?(?:/|$))[A-Za-z0-9_.][A-Za-z0-9_.-]*)*$")
ZERO = dict.fromkeys(map(ord, "​‌‍⁠﻿­"), None)


def normalize(t: str) -> str:
    """For the comparison with the forbidden words: entities and \\uXXXX decoded, NFKC, without detached diacritics
    nor invisible characters, spaces and newlines compressed, lower case."""
    t = html.unescape(t)
    t = re.sub(r"\\u([0-9a-fA-F]{4})", lambda m: chr(int(m.group(1), 16)), t)
    t = unicodedata.normalize("NFKC", t).translate(ZERO)
    t = "".join(c for c in unicodedata.normalize("NFD", t) if unicodedata.category(c) != "Mn")
    return re.sub(r"\s+", " ", t).lower()


def is_mark_line(line: str) -> bool:
    """A marker line of swarmer.sh (5.0) or of the 4.0 script."""
    return line.startswith(FILE_MARKS) or line.strip() in END_MARKS


def _spaced(s: str) -> str:
    """«-», «_», «.», «/», «\\» as spaces."""
    return re.sub(r"[-_./\\]+", " ", s)


def public_problems(text: str, words: list[str]) -> list[str]:
    out = [f"possible secret: {rx.pattern}" for rx in SECRETS if rx.search(text)]
    out += [f"e-mail address: {m.group(0).split('@')[0][:2]}…@…" for m in EMAIL.finditer(text)][:1]
    out += [f"machine path: {m.group(0)[:14]}…" for m in MACHINE_PATH.finditer(text)][:1]
    # also with the JSON escapes as spaces, with the separators as spaces (the entries of several words, as in the
    # names of the files) and with the percent encoding decoded
    unq = urllib.parse.unquote(text)
    forms = (normalize(text), normalize(re.sub(r"\\[nrtbf]", " ", text)), normalize(_spaced(text)), normalize(unq),
             normalize(_spaced(unq)))
    for i, w in enumerate(words):
        ws = {x for x in (normalize(w), normalize(_spaced(w))) if x.strip()}
        if any(x in n for x in ws for n in forms):
            out.append(f"word forbidden by the project (FORBIDDEN.txt), entry no. {i + 1}")
    for k, line in enumerate(text.splitlines(), 1):
        if is_mark_line(line):
            out.append(f"line {k}: a marker of swarmer.sh inside a file")
            break
    return out
